BashCompatScripts.MatchesBash:
set -euo pipefail
main() {
  local name="${1:-world}"
  printf 'Hello, %s!\n' "$name"
}
main "$@"

#!/usr/bin/env bash
set -e
usage() { echo "usage: $0 [-v] file" >&2; exit 2; }
verbose=0
while getopts ":vh" opt; do
  case "$opt" in
    v) verbose=1 ;;
    h) usage ;;
    \?) echo "bad option -$OPTARG" >&2; exit 2 ;;
  esac
done
shift $((OPTIND - 1))
echo "verbose=$verbose rest=$#"

retry() { local n=0; until "$@"; do n=$((n+1)); [ $n -ge 3 ] && return 1; done; }
retry false || echo "gave up"
retry true && echo ok

die() { echo "error: $*" >&2; exit 1; }
[[ -f missing.txt ]] || die "missing.txt not found"
echo unreachable

for i in {1..3}; do
  case $i in
    1) echo one ;;
    2) echo two ;;
    *) echo many ;;
  esac
done
